import { NextRequest, NextResponse } from 'next/server'

const OPTCG_API_BASE = 'https://optcgapi.com/api'

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ path: string[] }> }
) {
  const { path } = await params
  // Filter out empty strings (from trailing slashes) and join
  const pathString = path.filter(Boolean).join('/')
  const searchParams = request.nextUrl.searchParams.toString()
  // OPTCG API expects trailing slashes
  const url = `${OPTCG_API_BASE}/${pathString}/${searchParams ? `?${searchParams}` : ''}`

  console.log('One Piece API proxy - fetching:', url)

  try {
    const response = await fetch(url, {
      headers: {
        'Accept': 'application/json',
        'User-Agent': 'Pokemon-Resale-App/1.0',
      },
    })

    console.log('One Piece API proxy - response status:', response.status)

    if (!response.ok) {
      const errorText = await response.text()
      console.error('One Piece API proxy - error response:', errorText)
      return NextResponse.json(
        { error: `API returned ${response.status}`, details: errorText },
        { status: response.status }
      )
    }

    const data = await response.json()
    return NextResponse.json(data)
  } catch (error) {
    console.error('One Piece API proxy error:', error)
    return NextResponse.json(
      { error: 'Failed to fetch from One Piece API', details: String(error) },
      { status: 500 }
    )
  }
}
